        // ) Update Specific Module
        public function updateSpecificModule ($updateModuleId, $moduleName, $moduleUrlEdit, $moduleStatus) {
            $con = $GLOBALS["con"];
                               // 0
            if ($moduleUrlEdit != "") {
                $sql = "UPDATE module m SET "
                    . "m.moduleName = '$moduleName',"
                    . "m.moduleURL = '$moduleUrlEdit',"
                    . "m.moduleStatus = '$moduleStatus' WHERE "
                    . "m.moduleId = '$updateModuleId'";
                                      // 1
            } else if ($moduleUrlEdit == "") {
                $sql = "UPDATE module m SET "
                    . "m.moduleName = '$moduleName',"
                    . "m.moduleStatus = '$moduleStatus' WHERE "
                    . "m.moduleId = '$updateModuleId'";
            }
            $result = $con->query($sql);    
            return $result;
        }
