        // ) Add New Function
        public function addNewFunction ($functionName, 
                                       $functionURLEdit, 
                                       $selectedModuleId, 
                                       $functionModuleIdBelong, 
                                       $functionModuleIdExpansion, 
                                       $breadcrumbColumn1Id, 
                                       $breadcrumbColumn2Id, 
                                       $breadcrumbColumn3Id, 
                                       $breadcrumbColumn4Id, 
                                       $breadcrumbColumn5Id, 
                                       $breadcrumbColumn6Id, 
                                       $breadcrumbColumn7Id, 
                                       $breadcrumbColumn8Id, 
                                       $breadcrumbColumn9Id, 
                                       $breadcrumbColumn10Id,
                                       $functionURLStatus) {
            $con = $GLOBALS["con"];
            $sql = "INSERT INTO functions("
                . "functionName,"
                . "functionURL,"
                . "moduleId,"
                . "functionsModuleIdBelong,"
                . "functionsModuleIdExpansion,"
                . "breadcrumbColumn1Id,"
                . "breadcrumbColumn2Id,"
                . "breadcrumbColumn3Id,"
                . "breadcrumbColumn4Id,"
                . "breadcrumbColumn5Id,"
                . "breadcrumbColumn6Id,"
                . "breadcrumbColumn7Id,"
                . "breadcrumbColumn8Id,"
                . "breadcrumbColumn9Id,"
                . "breadcrumbColumn10Id,"
                . "functionURLStatus)"
                . "VALUES("
                . "'$functionName',"
                . "'$functionURLEdit',"
                . "'$selectedModuleId',"
                . "'$functionModuleIdBelong',"
                . "'$functionModuleIdExpansion',"
                . "'$breadcrumbColumn1Id',"
                . "'$breadcrumbColumn2Id',"
                . "'$breadcrumbColumn3Id',"
                . "'$breadcrumbColumn4Id',"
                . "'$breadcrumbColumn5Id',"
                . "'$breadcrumbColumn6Id',"
                . "'$breadcrumbColumn7Id',"
                . "'$breadcrumbColumn8Id',"
                . "'$breadcrumbColumn9Id',"
                . "'$breadcrumbColumn10Id',"
                . "'$functionURLStatus')";
            $con->query($sql) or die($con->error);
            return $insert_id = $con->insert_id;         
        } 
