        // ) Update Specific Function
        public function updateSpecificFunction ($updateFunctionId,
                                                $functionName, 
                                                $functionURLEdit, 
                                                $functionStatus,
                                                $selectedModuleId, 
                                                $functionModuleIdBelong, 
                                                $functionModuleIdExpansion, 
                                                $navigationTabTypeId, 
                                                $breadcrumbColumn1Id,
                                                $breadcrumbColumn2Id,
                                                $breadcrumbColumn3Id,
                                                $breadcrumbColumn4Id,
                                                $breadcrumbColumn5Id,
                                                $breadcrumbColumn6Id,
                                                $breadcrumbColumn7Id,
                                                $breadcrumbColumn8Id,
                                                $breadcrumbColumn9Id,
                                                $breadcrumbColumn10Id,
                                                $functionURLStatus) {
            $con = $GLOBALS["con"];
                                   // 0                    // 0                      
            if ($functionURLStatus != 1 & $functionURLEdit != "") {
                // Function URL Status      - Not Order to Assign URL
                // Function URL             - Passed
                $sql = "UPDATE functions f SET "
                    . "f.functionName = '$functionName',"
                    . "f.functionURL = '',"
                    . "f.moduleId = '$selectedModuleId',"
                    . "f.functionsModuleIdBelong = '$functionModuleIdBelong',"
                    . "f.functionsModuleIdExpansion = '$functionModuleIdExpansion',"
                    . "f.navigationTabTypeId = '$navigationTabTypeId',"
                    . "f.breadcrumbColumn1Id = '$breadcrumbColumn1Id',"
                    . "f.breadcrumbColumn2Id = '$breadcrumbColumn2Id',"
