                    . "f.breadcrumbColumn9Id = '$breadcrumbColumn9Id',"
                    . "f.breadcrumbColumn10Id = '$breadcrumbColumn10Id',"
                    . "f.functionStatus = '$functionStatus',"
                    . "f.functionURLStatus = '0' WHERE "
                    . "f.functionId = '$updateFunctionId'";
                                          // 0                    // 1
            } else if ($functionURLStatus != 1 & $functionURLEdit == "") {
                // Function URL Status      - Not Order to Assign URL
                // Function URL             - Not Passed
                $sql = "UPDATE functions f SET "
                    . "f.functionName = '$functionName',"
