                    . "f.functionStatus = '$functionStatus',"
                    . "f.functionURLStatus = '0' WHERE "
                    . "f.functionId = '$updateFunctionId'";
                                          // 1                    // 0
            } else if ($functionURLStatus == 1 & $functionURLEdit != "") {
                // Function URL Status      - Order to Assign URL
                // Function URL             - Passed
                $sql = "UPDATE functions f SET "
