                . "userName1,"
                . "userName2,"
                . "userName3,"
                . "emailId,"
                . "dateOfBirthdayId,"
                . "nicId,"
                . "profileImageId,"
                . "addressId,"
                . "roleId,"
                . "loginId)"
                . "VALUES("
                . "'$userName1',"
                . "'$userName2',"
                . "'$userName3',"
                . "'$emailId',"
                . "'$dateOfBirthdayId',"
                . "'$nicId',"
                . "'$profileImageId',"
                . "'$addressId',"
