        }
        // ) Add New User From Anyware
        public function addNewUserFromAnyware (
            $userName1,
            $userName2,
            $userName3,     

            $email,
            $nic,

            $dob,        
            $address,
            
            $contactNumber1,
            $contactTypeId1,

            $contactNumber2,
            $contactTypeId2,

            $profileImageEdit,           
            $roleId, 

            $createPassword,
            $confirmPassword 
        ) {
            $con = $GLOBALS["con"];

            $addNewEmailSql = "INSERT INTO email(email)VALUES('$email')";
            $con->query($addNewEmailSql) or die($con->error);
            $emailId = $con->insert_id; 

            $addNewNICSql = "INSERT INTO nic(nic)VALUES('$nic')";
            $con->query($addNewNICSql) or die($con->error);
            $nicId = $con->insert_id; 

            $addNewDOBSql = "INSERT INTO date_of_birthday(dateOfBirthday)VALUES('$dob')";
            $con->query($addNewDOBSql) or die($con->error);
            $dateOfBirthdayId = $con->insert_id;  

            $addNewAddressSql = "INSERT INTO address(address)VALUES('$address')";
            $con->query($addNewAddressSql) or die($con->error);
            $addressId = $con->insert_id;  

            $addNewProfileImage = "INSERT INTO profile_image(profileImage)VALUES('$profileImageEdit')";
            $con->query($addNewProfileImage) or die($con->error);
            $profileImageId = $con->insert_id; 
            
            $addNewPasswordSql = "INSERT INTO password(password)VALUES('$confirmPassword')";
            $con->query($addNewPasswordSql) or die($con->error);
            $passwordId = $con->insert_id;   

            $addNewLoginSql = "INSERT INTO login(emailId, passwordId)"
                . "VALUES('$emailId','$passwordId')";
            $con->query($addNewLoginSql) or die($con->error);
            $loginId = $con->insert_id;
        
            $addNewUserSql = "INSERT INTO user("
                . "userName1,"
                . "userName2,"
                . "userName3,"

                . "emailId,"
                . "nicId,"

                . "dateOfBirthdayId,"
                . "addressId,"

                . "profileImageId,"
                . "roleId,"

                . "loginId"

                . ")VALUES("
                . "'$userName1',"
                . "'$userName2',"
                . "'$userName3',"

                . "'$emailId',"
                . "'$nicId',"

                . "'$dateOfBirthdayId',"
                . "'$addressId',"

                . "'$profileImageId',"
                . "'$roleId',"

                . "'$loginId'"
                . ")";
            $con->query($addNewUserSql) or die($con->error);
            $updateUserId = $con->insert_id;    

            $addNewContactId1 = "INSERT INTO contact("
                . "contactNumber,"
                . "contactTypeId,"
                . "userId"
                . ")VALUES("
                . "'$contactNumber1',"
                . "'$contactTypeId1',"
                ."'$updateUserId')";
            $con->query($addNewContactId1) or die($con->error);
            $contactId1 = $con->insert_id;   

            $addNewContactId2 = "INSERT INTO contact("
                . "contactNumber,"
                . "contactTypeId,"
                . "userId"
                . ")VALUES("
                . "'$contactNumber2',"
                . "'$contactTypeId2',"
                ."'$updateUserId')";
            $con->query($addNewContactId2) or die($con->error);
            $contactId2 = $con->insert_id; 

            $updateUserContactId1 = "UPDATE user u SET "
                . "u.contactId1 = '$contactId1' WHERE "
                . "u.userId = '$updateUserId'";
            $con->query($updateUserContactId1) or die($con->error);

            $updateUserContactId2 = "UPDATE user u SET "
                . "u.contactId2 = '$contactId2' WHERE "
                . "u.userId = '$updateUserId'";
            $con->query($updateUserContactId2) or die($con->error);

            return $updateUserId;

        }
