                . "userId = '$updateUserId'";
            $result = $con->query($sql) or die($con->error);
            return $result;
        }
        // ) Get All Users Count
        public function getAllUsersCount () {
            $con = $GLOBALS["con"];
            $sql = "SELECT COUNT(*) as allCount FROM user";
            $result = $con->query($sql);
            $countRow = $result->fetch_assoc();
            $allCount = $countRow["allCount"];
            return $allCount;
        } 
        // ) Get Active User Count
        public function getActiveUsersCount () {
            $con = $GLOBALS["con"];
            $sql = "SELECT COUNT(*) as activeCount FROM "
                . "USER WHERE "
                . "userStatus = '1' AND "
                . "userDeleteStatus = '0'";
            $result = $con->query($sql);
            $countRow = $result->fetch_assoc();
            $activeCount = $countRow["activeCount"];
            return $activeCount;
        } 
        // ) Get Inactive Not Temporary Deleted User Count
        public function getInactiveNotTemporaryDeletedUserCount () {
            $con = $GLOBALS["con"];
            $sql = "SELECT COUNT(*) as inactiveNotTemporaryDeletedCount FROM "
                . "USER WHERE "
                . "userStatus = '0' AND "
                . "userDeleteStatus = '0'";
            $result = $con->query($sql);
            $countRow = $result->fetch_assoc();
            $inactiveNotTemporaryDeletedCount = $countRow["inactiveNotTemporaryDeletedCount"];
            return $inactiveNotTemporaryDeletedCount;
        }
        // ) Get Inactive Temporary Deleted User Count
        public function getInactiveTemporaryDeletedUserCount () {
            $con = $GLOBALS["con"];
            $sql = "SELECT COUNT(*) as inactiveTemporaryDeletedCount FROM "
                . "USER WHERE "
                . "userStatus = '0' AND "
                . "userDeleteStatus = '1'";
            $result = $con->query($sql);
            $countRow = $result->fetch_assoc();
            $inactiveTemporaryDeletedCount = $countRow["inactiveTemporaryDeletedCount"];
            return $inactiveTemporaryDeletedCount;
        }  
        // ) Get All Online User Count
        public function getAllOnlineUserCount () {
            $con = $GLOBALS["con"];
            $sql = "SELECT COUNT(*) as onlineCount FROM user u, login l WHERE "
                . "l.loginId = u.loginId AND "
                . "l.loginStatus = '1'";
            $result = $con->query($sql) or die($con->error);
            $countRow = $result->fetch_assoc();
            $onlineCount = $countRow["onlineCount"];
            return $onlineCount;
        } 
        // ) Get All Offline User Count
        public function getAllOfflineUserCount () { 
            $con = $GLOBALS["con"];
            $sql = "SELECT COUNT(*) as offlineCount FROM user u, login l WHERE "
                . "l.loginId = u.loginId AND "
                . "l.loginStatus = '0'";
            $result = $con->query($sql) or die($con->error);
            $countRow = $result->fetch_assoc();
            $offlineCount = $countRow["offlineCount"];
            return $offlineCount;
        }                                      
