                . "rf.functionId = f.functionId AND "
                . "f.functionStatus = '1' AND "
                . "rf.roleId = '$updateRoleId'";
            $result = $con->query($sql) or die($conn->error);
            return $result;
        }
        // ) Get All Active Functions in Role Functions By ModuleId
        public function getAllActiveFunctionsInRoleFunctionsByModuleId ($updateModuleId, $updateRoleId) {
            $conn = $GLOBALS["con"];
            $sql = "SELECT * FROM role_functions rf, role r, functions f, module m WHERE "
                . "f.functionId = rf.functionId AND "
                . "r.roleId = rf.roleId AND "
                . "rf.roleId = '$updateRoleId' AND "
                . "f.moduleId = m.moduleId AND "
                . "f.moduleId = '$updateModuleId' AND "
                . "functionStatus = '1' "
                . "ORDER BY functionName ASC";
            $result = $conn->query($sql) or die($conn->error);
            return $result;        
        }
