            $updateBreadcrumbId, 
            $breadcrumbName, 
            $liCSS, 
            $liAriaCurrent, 
            $aHrefEdit, 
            $breadcrumbStatus
        ) {
            $con = $GLOBALS["con"];
                           // 0
            if ($aHrefEdit != "") {
                // Breadcrumb URL       - Passed
                $sql = "UPDATE breadcrumb b SET "
                    . "b.breadcrumbName = '$breadcrumbName',"
                    . "b.breadcrumbLiCss = '$liCSS',"
                    . "b.breadcrumbLiAriaCurrent = '$liAriaCurrent',"
                    . "b.breadcrumbURL = '$aHrefEdit',"
                    . "b.breadcrumbStatus = '$breadcrumbStatus'"
                    . "WHERE "
                    . "b.breadcrumbId = '$updateBreadcrumbId'";
                                  // 1
            } else if ($aHrefEdit == "") {                
                // Breadcrumb URL       - Not Passed
                $sql = "UPDATE breadcrumb b SET "
                    . "b.breadcrumbName = '$breadcrumbName',"
                    . "b.breadcrumbLiCss = '$liCSS',"
                    . "b.breadcrumbStatus = '$breadcrumbStatus',"
                    . "b.breadcrumbLiAriaCurrent = '$liAriaCurrent'"
                    . "WHERE "
                    . "b.breadcrumbId = '$updateBreadcrumbId'";
            }
            $result = $con->query($sql) or die($con->error);   
            return $result;
        }      
