        // ) Get Specific Active Navigation Tabs In Role Navigation Tabs By Navigation Tab Type Id
        public function getSpecificActiveNavigationTabsInRoleNavigationTabsByNavigationTabTypeId ($navigationTabTypeId, $updateRoleId) {
            $con = $GLOBALS["con"];
            $sql = "SELECT * FROM "
                . "navigation_tab nt, "
                . "navigation_tab_type ntt, "
                . "role_navigation_tabs rnt, "
                . "role_navigation_tab_type rntt, "
                . "navigation_tab_type_navigation_tab nttnt, "
                . "role r "
                . "WHERE "

                . "nt.navigationTabId = rnt.navigationTabId AND "
                . "nt.navigationTabId = nttnt.navigationTabId AND "

                . "ntt.navigationTabTypeId = rntt.navigationTabTypeId AND "
                . "ntt.navigationTabTypeId = nttnt.navigationTabTypeId AND "

                . "rnt.roleId = rntt.roleId AND "
                . "rnt.navigationTabId = nttnt.navigationTabId AND "
                . "rnt.roleId = r.roleId AND "

                . "rntt.navigationTabTypeId = nttnt.navigationTabTypeId AND "
                . "rntt.roleId = r.roleId AND "


                . "rntt.roleId = '$updateRoleId' AND "      
                . "rntt.navigationTabTypeId = '$navigationTabTypeId' AND "
                . "nt.navigationTabStatus = '1'"
                . "ORDER BY nt.navigationTabName ASC";
            $result = $con->query($sql);
            return $result;
        }
