        public function getSpecificActiveNavigationTabsInUserNavigationTabsByNavigationTabTypeId ($navigationTabTypeId, $updateUserId) {
            $con = $GLOBALS["con"];
            $sql = "SELECT * FROM navigation_tab nt, navigation_tab_type ntt, user_navigation_tabs unt, navigation_tab_type_navigation_tab nttnt, user u, user_navigation_tab_type untt WHERE "
                . "nt.navigationTabId = unt.navigationTabId AND "
                . "nttnt.navigationTabId = unt.navigationTabId AND "
                . "untt.userId = unt.userId AND "
                . "u.userId = unt.userId AND "
                . "u.userId = untt.userId AND "
                . "untt.userId = '$updateUserId' AND "
                . "nt.navigationTabId = nttnt.navigationTabId AND "
                . "nttnt.navigationTabTypeId = untt.navigationTabTypeId AND "                
                . "nttnt.navigationTabTypeId = ntt.navigationTabTypeId AND "                
                . "untt.navigationTabTypeId = ntt.navigationTabTypeId AND "                
                . "nttnt.navigationTabTypeId = '$navigationTabTypeId' AND "
                . "nt.navigationTabStatus = '1'"
                . "ORDER BY nt.navigationTabName ASC";
            $result = $con->query($sql);
            return $result;
        }
