        // Get Specific Year Month Client Hire Driver Request Report By clientServiceId fleetId
        public function getSpecificYearMonthClientHireDriverRequestReportclientServiceIdfleetId($clientServiceId, $fleetId){
            $con = $GLOBALS["con"];
            $sql = "SELECT * FROM "
                . "client_requests cr, "
                . "client_services cs, "
                . "process_status ps, "
                . "hire_driver_request hdr, "
                . "class_of_vehicles cov, "                
                . "colors cssc, "
                . "user u, "
                . "driver d, "
                . "fleet f, "
                . "profile_image pi, "
                . "email e, "
                . "contact con "
                . "WHERE "
                . "cs.clientServiceId  = cr.clientServiceId AND "
                . "ps.cssColorId = cssc.colorId AND "
                . "ps.processStatusId = cr.processStatusId AND "
                . "hdr.clientRequestId = cr.clientRequestId  AND "
                . "f.fleetId = hdr.fleetId AND "
                . "hdr.driverId = d.driverId AND "
                . "d.userId = u.userId AND "
                . "pi.profileImageId = u.profileImageId AND "
                . "u.emailId = e.emailId  AND "
                . "u.contactId1 = con.contactId AND "
                . "cov.classOfVehicleId = hdr.classOfVehicleId  AND "
                . "cr.clientRequestCompleted = '1' AND "
                . "f.fleetId = '$fleetId' AND "
                . "cs.clientServiceId = '$clientServiceId'"
                . "ORDER BY cr.clientRequestId ASC";
            $result = $con->query($sql) or die($con->error);
            return $result;
        }
