            $con = $GLOBALS["con"];
            $sql = "UPDATE client_services SET "
                . "clientServiceDeleteStatus = '0'," 
                . "clientServiceStatus = '0' WHERE "
                . "clientServiceId = '$updateClientService'";
            $result = $con->query($sql) or die($con->error);
            return $result;
        }  
