        // ) Get Specific Driver By Driver Id
        public function getSpecificDriverByDriverId($driverId){
            $con = $GLOBALS["con"];
            $sql = "SELECT * FROM "
                . "user u, "
                . "email e, "
                . "date_of_birthday dob, "
                . "nic nic, "
                . "profile_image pi, "
                . "contact con, "
                . "address adr, "
                . "password p, "
                . "login l, "
                . "driver d "
                . "WHERE "
                . "u.userId = d.userId AND "
                . "u.emailId = e.emailId AND "
                . "u.dateOfBirthdayId = dob.dateOfBirthdayId AND "
                . "u.nicId = nic.nicId AND "
                . "u.profileImageId = pi.profileImageId AND "
                . "u.contactId1 = con.contactId AND "
                . "u.addressId = adr.addressId AND "
                . "u.loginId = l.loginId AND "
                . "p.passwordId = l.passwordId AND "
                . "d.driverId = '$driverId'";
            $result = $con->query($sql) or die($con->error);
            return $result;       
        }
