        // ) Get Specific Driver License By driverId
        public function getSpecificDrivingLicenseByDriverId ($driverId) {
            $con = $GLOBALS["con"];
            $sql = "SELECT * FROM "
                . "driver d, "
                . "driver_license_othername dlon, "
                . "user u, "
                . "nic nic, "
                . "date_of_birthday dob, "
                . "driver_license_number dln, "
                . "driver_licenses dl "
                . "WHERE "
                . "dl.driverLicenseOthernameId = dlon.driverLicenseOthernameId AND "
                . "dl.driverLicenseNumberId = dln.driverLicenseNumberId  AND "
                . "u.userId = d.userId AND "
                . "u.nicId = nic.nicId AND "
                . "u.dateOfBirthdayId = dob.dateOfBirthdayId AND "
                . "dl.driverLicenseId = d.driverLicenseId AND "
                . "d.driverId = '$driverId'";
            $result = $con->query($sql) or die($con->error);
            return $result;
        }
