        // 2) Get Specific Driver Driver Tasks Count - driverUserId processId
        public function getSpecificDriverDriverTasksRequestsdriverUserIdprocessStatusIdCount ($processStatusId, $userId) {
            $con = $GLOBALS["con"];
            $sql = "SELECT COUNT(*) as allCount FROM "
                . "user u, "
                . "driver_tasks dt, "
                . "driver d, "
                . "profile_image pi, "
                . "client_requests cr, "
                . "colors cssc, "
                . "process_status ps, "
                . "client_services cs "
                . "WHERE "
                . "ps.processStatusId = cr.processStatusId AND "
                . "ps.processStatusId = '$processStatusId' AND "
                . "ps.cssColorId = cssc.ColorId AND "
                . "u.profileImageId = pi.profileImageId AND "
                . "cr.clientServiceId = cs.clientServiceId AND "
                . "cr.clientRequestId = dt.clientRequestId AND "
                . "d.driverId = dt.driverId AND "
                . "u.userId = d.userId AND "
                . "d.userId = '$userId'";
            $result = $con->query($sql) or die($con->error);
            $countRow = $result->fetch_assoc();
            $allCount = $countRow["allCount"];
            return $allCount;
        }
