        // ) Get All Fleet Fuel Supply Requests
        public function getAllFleetFuelSupplyAvailableRequestPayments () {
            $con= $GLOBALS["con"];
            $sql = "SELECT * FROM "
                    . "fleet_fuel_supply_request ffsr, "
                    . "fuel_stations fs, "
                    . "fuel_type ft, "
                    . "finance fi, "
                    . "finance_type fit, "
                    . "process_status ps, "
                    . "colors btspc, "
                    . "fleet f "
                    . "WHERE "
                    . "ffsr.fuelStationId = fs.fuelStationId AND "
                    . "ffsr.fuelTypeId = ft.fuelTypeId AND "
                    . "ffsr.fleetId = f.fleetId AND "
                    . "ffsr.financeId = fi.financeId AND "
                    . "ffsr.financeTypeId = fit.financeTypeId AND "
                    . "ffsr.processStatusId = ps.processStatusId AND "
                    . "btspc.ColorId = ps.cssColorId AND "
                    . "ffsr.fleetFuelSupplyRequestPaymentRequestStatus = '1' AND "
                    . "ffsr.fleetFuelSupplyRequestCompleted = '0' AND "
                    . "ffsr.fleetFuelSupplyRequestCancelStatus = '0'";
            $result= $con->query($sql) or die($con->error);
            return $result;
        }
