        // ) Update Specific Vehicle Overview
        public function updateSpecificVehicleOverview (
                $vehicleStatus,
                                        
                $vehicleManufacturerId,
                $vehicleModelId, 

                $vehicleColorId, 
                $classOfVehicleId, 

                $vehicleImageEdit, 
                $vehicleRegistrationNumber,

                $vehicleCurrentStatusId,
                
                $updateVehicleId
            ) {
            $con = $GLOBALS["con"];
            if ($vehicleImageEdit == "") {
                $sql = "UPDATE "
                    . "vehicle v, "
                    . "vehicle_registration_number vrn "
                    . "SET "
                    . "v.vehicleStatus = '$vehicleStatus',"   

                    . "v.vehicleManufacturerId = '$vehicleManufacturerId',"
                    . "v.vehicleModelId = '$vehicleModelId',"
                    
                    . "v.vehicleColorId = '$vehicleColorId',"
                    . "v.classOfVehicleId = '$classOfVehicleId',"

                    . "vrn.vehicleRegistrationNumber = '$vehicleRegistrationNumber',"

                    . "v.vehicleCurrentStatusId = '$vehicleCurrentStatusId' "
                    . "WHERE "
                    . "vrn.vehicleRegistrationNumberId = v.vehicleRegistrationNumberId AND "
                    . "v.vehicleId = '$updateVehicleId'";
            } else if ($vehicleImageEdit != "") {
                $sql = "UPDATE "
                    . "vehicle v, "
                    . "vehicle_registration_number vrn "
                    . "SET "
                    . "v.vehicleStatus = '$vehicleStatus',"   

                    . "v.vehicleManufacturerId = '$vehicleManufacturerId',"
                    . "v.vehicleModelId = '$vehicleModelId',"
                    
                    . "v.vehicleColorId = '$vehicleColorId',"
                    . "v.classOfVehicleId = '$classOfVehicleId',"

                    . "vrn.vehicleRegistrationNumber = '$vehicleRegistrationNumber',"
                    . "v.vehicleImage = '$vehicleImageEdit',"

                    . "v.vehicleCurrentStatusId = '$vehicleCurrentStatusId' "
                    . "WHERE "
                    . "vrn.vehicleRegistrationNumberId = v.vehicleRegistrationNumberId AND "
                    . "v.vehicleId = '$updateVehicleId'";
            }
            $result= $con->query($sql) or die($con->error);
            return $result;
        }
        
