    /* (34) Vehicle Book */
        // 1) Add New Vehicle Book
        public function addNewVehicleBook(
                $chassisNumber,

                $currentOwner, 
                $currentOwnerAddress, 

                $currentOwnerID, 

                $vehicleConditionId, 
                $specialNotes,   

                $absoluteOwner, 
                $engineNumber,

                $vehicleCylinderCapacityId,                                 

                $classOfVehicleIdTax,  
                $vehicleRegistratedStatusId,

                $fuelTypeId, 

                $countryId,   
                
                $classOfVehicleIdManufac,
                $wheelBase, 

                $overHang, 
                $typeOfBodyId, 

                $yearOfManufactureId,           
                                        
                $previousOwnerName,        
                $previousOwnerAddress,         

                $previousOwnerTransferredDate,          
                $totalPreviousOwners,      

                $seatingCapacity,     

                $weightUnladen,           
                $weightGross,     

                $tyreSizeFront,          
                $tyreSizeRear,

                $tyreSizeDual,         
                $tyreSizeSingle,  

                $length,          
                $width,       

                $height,       
                $internalHeight,       

                $provincialCouncilId,        
                $dateOfFirstRegistration,      

                $taxesPayable,       

                $updateVehicleId
            ) {
            $con = $GLOBALS["con"];

            $sqlChassisNumber = "INSERT INTO chassis_numbers("
                . "chassisNumber"
                . ")VALUES("
                . "'$chassisNumber'"
                .")";
            $con->query($sqlChassisNumber) or die($con->error);
            $chassisNumberId = $con->insert_id;

            $sqlEngineNumber = "INSERT INTO engine_number("
                . "engineNumber"
                . ")VALUES("
                . "'$engineNumber'"
                .")";
            $con->query($sqlEngineNumber) or die($con->error);
            $engineNumberId  = $con->insert_id;

            $sqlVehicleBook = "INSERT INTO vehicle_book("
                . "chassisNumberId,"

                . "currentOwner,"
                . "currentOwnerAddress,"

                . "currentOwnerID,"

                . "conditionId,"
                . "specialNotes,"

                . "absoluteOwner,"
                . "engineNumberId,"

                . "ccId,"

                . "taxationClassId,"
                . "statusWhenRegisteredId,"

                . "fuelTypeId,"

                . "countryOfOriginId,"

                . "manudacturesDescription,"
                . "wheelBase,"

                . "overHang,"
                . "typeOfBodyId,"

                . "yearOfManufactureId,"

                . "previousOwnerName,"
                . "previousOwnerAddress,"

                . "previousOwnerTransferredDate,"
                . "totalPreviousOwners,"

                . "seatingCapacity,"

                . "weightUnladen,"
                . "weightGross,"

                . "tyreSizeFront,"
                . "tyreSizeRear,"

                . "tyreSizeDual,"
                . "tyreSizeSingle,"

                . "length,"
                . "width,"

                . "height,"
                . "internalHeight,"

                . "provincialCouncilId,"
                . "dateOfFirstRegistration,"

                . "taxesPayable"
                . ")VALUES("
                . "'$chassisNumberId',"

                . "'$currentOwner',"
                . "'$currentOwnerAddress',"

                . "'$currentOwnerID',"

                . "'$vehicleConditionId',"
                . "'$specialNotes',"

                . "'$absoluteOwner',"
                . "'$engineNumberId',"

                . "'$vehicleCylinderCapacityId',"

                . "'$classOfVehicleIdTax',"
                . "'$vehicleRegistratedStatusId',"

                . "'$fuelTypeId',"

                . "'$countryId',"

                . "'$classOfVehicleIdManufac',"
                . "'$wheelBase',"

                . "'$overHang',"
                . "'$typeOfBodyId',"

                . "'$yearOfManufactureId',"

                . "'$previousOwnerName',"
                . "'$previousOwnerAddress',"

                . "'$previousOwnerTransferredDate',"
                . "'$totalPreviousOwners',"

                . "'$seatingCapacity',"

                . "'$weightUnladen',"
                . "'$weightGross',"

                . "'$tyreSizeFront',"
                . "'$tyreSizeRear',"

                . "'$tyreSizeDual',"
                . "'$tyreSizeSingle',"

                . "'$length',"
                . "'$width',"

                . "'$height',"
                . "'$internalHeight',"

                . "'$provincialCouncilId',"
                . "'$dateOfFirstRegistration',"

                . "'$taxesPayable'"
                .")";   
            $con->query($sqlVehicleBook) or die($con->error);
            $vehicleBookId = $con->insert_id; 

            $sqlVehicle = "UPDATE vehicle v SET "
                . "v.vehicleBookId = '$vehicleBookId',"
                . "v.vehicleBookStatus = '1' WHERE "
                . "v.vehicleId = '$updateVehicleId'";
            $con->query($sqlVehicle) or die($con->error);
        } 
        // ) Update Specific Vehicle Overview
        public function updateSpecificVehicleBook (
                $vehicleRegistrationNumber,
                $chassisNumber,

                $currentOwner, 
                $currentOwnerAddress, 

                $currentOwnerID, 

                $vehicleConditionId, 
                $specialNotes,   

                $absoluteOwner, 
                $engineNumber,

                $vehicleCylinderCapacityId,                                 
                $classOfVehicleId,

                $classOfVehicleIdTax,  
                $vehicleRegistratedStatusId,

                $fuelTypeId, 
                $vehicleManufacturerId,

                $countryId,   
                $vehicleModelId,
                
                $classOfVehicleIdManufac,
                $wheelBase, 

                $overHang, 
                $typeOfBodyId, 

                $yearOfManufactureId,           
                $vehicleColorId, 
                                            
                $previousOwnerName,        
                $previousOwnerAddress,         

                $previousOwnerTransferredDate,          
                $totalPreviousOwners,      

                $seatingCapacity,     

                $weightUnladen,           
                $weightGross,     

                $tyreSizeFront,          
                $tyreSizeRear,

                $tyreSizeDual,         
                $tyreSizeSingle,  

                $length,          
                $width,       

                $height,       
                $internalHeight,       

                $provincialCouncilId,        
                $dateOfFirstRegistration,      

                $taxesPayable,       

                $vehicleBookId,
                $updateVehicleId         
            ) {
            $con = $GLOBALS["con"];
            $sql = "UPDATE "
                . "vehicle v, "
                . "vehicle_book vb, "
                . "vehicle_registration_number vrn, "
                . "engine_number en, "
                . "chassis_numbers cn "
                . "SET "            
                . "vrn.vehicleRegistrationNumber = '$vehicleRegistrationNumber',"                        
                . "cn.chassisNumber = '$chassisNumber',"

                . "vb.currentOwner = '$currentOwner',"
                . "vb.currentOwnerAddress = '$currentOwnerAddress',"

                . "vb.currentOwnerID = '$currentOwnerID',"

                . "vb.conditionId = '$vehicleConditionId',"
                . "vb.specialNotes = '$specialNotes',"

                . "vb.absoluteOwner = '$absoluteOwner',"
                . "en.engineNumber = '$engineNumber',"

                . "vb.ccId = '$vehicleCylinderCapacityId',"
                . "v.classOfVehicleId = '$classOfVehicleId',"
                
                . "vb.taxationClassId = '$classOfVehicleIdTax',"
                . "vb.statusWhenRegisteredId = '$vehicleRegistratedStatusId',"

                . "vb.fuelTypeId = '$fuelTypeId',"
                . "v.vehicleManufacturerId = '$vehicleManufacturerId',"

                . "vb.countryOfOriginId = '$countryId',"
                . "v.vehicleModelId = '$vehicleModelId',"

                . "vb.manudacturesDescription = '$classOfVehicleIdManufac',"
                . "vb.wheelBase = '$wheelBase',"

                . "vb.overHang = '$overHang',"
                . "vb.typeOfBodyId = '$typeOfBodyId',"

                . "vb.yearOfManufactureId = '$yearOfManufactureId',"
                . "v.vehicleColorId = '$vehicleColorId',"
                
                . "vb.previousOwnerName = '$previousOwnerName',"
                . "vb.previousOwnerAddress = '$previousOwnerAddress',"

                . "vb.previousOwnerTransferredDate = '$previousOwnerTransferredDate',"
                . "vb.totalPreviousOwners = '$totalPreviousOwners',"

                . "vb.seatingCapacity = '$seatingCapacity',"

                . "vb.weightUnladen = '$weightUnladen',"
                . "vb.weightGross = '$weightGross',"

                . "vb.tyreSizeFront = '$tyreSizeFront',"
                . "vb.tyreSizeRear = '$tyreSizeRear',"

                . "vb.tyreSizeDual = '$tyreSizeDual',"
                . "vb.tyreSizeSingle = '$tyreSizeSingle',"

                . "vb.length = '$length',"
                . "vb.width = '$width',"

                . "vb.height = '$height',"
                . "vb.internalHeight = '$internalHeight',"

                . "vb.provincialCouncilId = '$provincialCouncilId',"
                . "vb.dateOfFirstRegistration = '$dateOfFirstRegistration',"

                . "vb.taxesPayable = '$taxesPayable' "
                . "WHERE "
                . "v.vehicleId = '$updateVehicleId' AND "
                . "vb.vehicleBookId  = '$vehicleBookId' AND "
                . "vb.engineNumberId = en.engineNumberId  AND "
                . "vb.chassisNumberId = cn.chassisNumberId  AND "
                . "v.vehicleBookId  = vb.vehicleBookId AND "
                . "v.vehicleRegistrationNumberId = vrn.vehicleRegistrationNumberId";
            $result= $con->query($sql) or die($con->error);
            return $result;
        }
