        // 3) Get Specific Vehicle Book Overview - vehicleId
        public function getSpecificVehicleBookOverview($vehicleId){
            $con = $GLOBALS["con"];
            $sql = "SELECT * FROM vehicle v, "
                . "vehicle_book vb, "
                . "vehicle_current_status vcs, "
                . "vehicle_manufacturers vmf, "
                . "fuel_type ft, "
                . "year y, "
                . "vehicle_registration_number vrn, "
                . "class_of_vehicles cov, "
                . "vehicle_model vm, "
                . "vehicle_color vc, "
                . "country c, "
                . "chassis_numbers cn, "
                . "vehicle_condition veco, "
                . "engine_number en, "
                . "vehicle_cylinder_capacity vcc, "
                . "vehicle_registrated_status vrs, "
                . "vehicle_type_of_body vtob, "
                . "provincial_council pc "
                . "WHERE "
                . "v.vehicleManufacturerId = vmf.vehicleManufacturerId AND "
                . "vm.vehicleManufacturerId = vmf.vehicleManufacturerId AND "
                . "v.vehicleCurrentStatusId = vcs.vehicleCurrentStatusId  AND "
                . "vb.fuelTypeId = ft.fuelTypeId  AND "
                . "v.vehicleBookId = vb.vehicleBookId AND "
                . "y.yearId = vb.yearOfManufactureId AND "
                . "pc.provincialCouncilId = vb.provincialCouncilId AND "
                . "v.vehicleRegistrationNumberId = vrn.vehicleRegistrationNumberId AND "
                . "v.classOfVehicleId = cov.classOfVehicleId AND "
                . "v.vehicleModelId = vm.vehicleModelId AND "
                . "v.vehicleColorId = vc.vehicleColorId AND "
                . "vb.countryOfOriginId = c.countryId AND "
                . "vb.chassisNumberId = cn.chassisNumberId AND "
                . "vb.conditionId = veco.vehicleConditionId AND "
                . "vb.engineNumberId = en.engineNumberId AND "
                . "vb.ccId = vcc.vehicleCylinderCapacityId AND "
                . "vb.statusWhenRegisteredId = vrs.vehicleRegistratedStatusId AND "
                . "vb.typeOfBodyId = vtob.vehicleTypeOfBodyId AND "
                . "v.vehicleId = '$vehicleId'";
