            $con = $GLOBALS["con"];
            if ($warehouseImageEdit != "") {
                $sql = "INSERT INTO warehouse("
                    . "warehouseName,"
                    . "cityId,"
                    // . "warehouseLocationURL,"
                    . "warehouseImage"
                    . ")VALUES("
                    . "'$warehouseName',"
                    . "'$cityId',"
                    // . "'$warehouseLocationURL',"
                    . "'$warehouseImageEdit'"
                    . ")";
            } else if ($warehouseImageEdit == "") {
                $sql = "INSERT INTO warehouse("
                    . "warehouseName,"
                    . "cityId"
                    // . "warehouseLocationURL"
                    . ")VALUES("
                    . "'$warehouseName',"
                    . "'$cityId'"
                    // . "'$warehouseLocationURL'"
                    . ")";
            }
            $result = $con->query($sql) or die($con->error);
            return $result;        
        }
