        // ) Update Warehouse Section To Nav Link Active D Block
        public function updateWarehouseSectionDisplayToNavLinkActiveDBlock ($updateWarehouseSectionId) {
            $con = $GLOBALS["con"];
            $sql1 = "UPDATE warehouse_sections SET warehouseSectionNavLink = 'nav-link'";
            $result1 = $con->query($sql1) or die($con->error); 
            $sql2 = "UPDATE warehouse_sections SET warehouseSectionNavLink = 'nav-link active' WHERE warehouseSectionId = '$updateWarehouseSectionId'";
            $result2 =  $con->query($sql2) or die($con->error); 
            $sql3 = "UPDATE warehouse_sections SET warehouseSectionDisplay = 'd-none'";
            $result3 =  $con->query($sql3) or die($con->error); 
            $sql4 = "UPDATE warehouse_sections SET warehouseSectionDisplay = 'd-block' WHERE warehouseSectionId = '$updateWarehouseSectionId'";
            $result4 = $con->query($sql4) or die($con->error); 
            return $result1." ".$result2." ".$result3." ".$result4;           
        }
