        // 6) Update Specific Product        
        public function updateSpecificProduct(
            $productManufacturerId,
            $productName,
            
            $productCategoryId,
            $productUnitMeasureValue,

            $productImageEdit,
            $productStatus,

            $updateProductId
        ){
            $con = $GLOBALS["con"];
            if ($productImageEdit == "") {
                $sql = "UPDATE products SET "
                    . "productManufacturerId = '$productManufacturerId',"
                    . "productName = '$productName',"
                    
                    . "productCategoryId = '$productCategoryId',"
                    . "productUnitMeasureValue = '$productUnitMeasureValue',"

                    . "productStatus = '$productStatus'"
                    . "WHERE "
                    . "productId = '$updateProductId'";
            } else if ($productImageEdit != "") {
                $sql = "UPDATE products SET "
                    . "productManufacturerId = '$productManufacturerId',"
                    . "productName = '$productName',"
                    
                    . "productCategoryId = '$productCategoryId',"
                    . "productUnitMeasureValue = '$productUnitMeasureValue',"

                    . "productImage = '$productImageEdit',"
                    . "productStatus = '$productStatus'"
                    . "WHERE "
                    . "productId = '$updateProductId'";
            }
            $result = $con->query($sql) or die($con->error);  
            return $result;
        } 
