        // ) Update Product Category To Nav Link Active D Block
        public function updateProductCategoryDisplayToNavLinkActiveDBlock ($updateProductCategoryId) {
            $con = $GLOBALS["con"];
            $sql1 = "UPDATE product_category SET productCategoryNavLink = 'nav-link'";
            $result1 = $con->query($sql1) or die($con->error); 
            $sql2 = "UPDATE product_category SET productCategoryNavLink = 'nav-link active' WHERE productCategoryId = '$updateProductCategoryId'";
            $result2 =  $con->query($sql2) or die($con->error); 
            $sql3 = "UPDATE product_category SET productCategoryDisplay = 'd-none'";
            $result3 =  $con->query($sql3) or die($con->error); 
            $sql4 = "UPDATE product_category SET productCategoryDisplay = 'd-block' WHERE productCategoryId = '$updateProductCategoryId'";
            $result4 = $con->query($sql4) or die($con->error); 
            return $result1." ".$result2." ".$result3." ".$result4;           
        }
