        // 1) Get Specific Inventory Products By roleId userId warehouseId
        public function getSpecificInventoryProductsByRoleIdUserIdWarehouseId($roleId, $userId, $warehouseId){
            $con = $GLOBALS["con"];
            $sql = "SELECT * FROM "
                . "role_access_to_warehouse_section_warehouse_sections ratwsws, "
                . "user_access_to_warehouse_section_warehouse_sections uatwsws, "
                . "role r, "
                . "user u, "
                . "inventory_sections_products isp, "
                . "products p, "
                . "warehouse w, "
                . "warehouse_sections ws, "
                . "product_category pc, "
                . "product_manufacturer pm, "
                . "product_unit_types put, "
                . "product_unit_measure pum "
                . "WHERE "
                . "ratwsws.warehouseId = uatwsws.warehouseId AND "
                . "ratwsws.warehouseSectionId = uatwsws.warehouseSectionId AND "
                . "ratwsws.roleId = r.roleId AND "
                . "ratwsws.warehouseId = w.warehouseId AND "
                . "ratwsws.warehouseSectionId = ws.warehouseSectionId AND "
                . "uatwsws.userId = u.userId AND "
                . "uatwsws.warehouseId = w.warehouseId AND "
                . "uatwsws.warehouseSectionId = ws.warehouseSectionId AND "
                . "isp.warehouseId = w.warehouseId AND "
                . "isp.warehouseSectionId = ws.warehouseSectionId AND "
                . "isp.productId = p.productId AND "
                . "p.productCategoryId = pc.productCategoryId AND "
                . "p.productManufacturerId = pm.productManufacturerId AND " 
                . "pc.productUnitTypeId = put.productUnitTypeId  AND " 
                . "pc.productUnitMeasureId  = pum.productUnitMeasureId AND " 
                . "w.warehouseId = ws.warehouseId AND "
                . "r.roleId = '$roleId' AND "
                . "u.userId = '$userId' AND "
                . "w.warehouseId  = '$warehouseId' " 
                . "ORDER BY pm.productManufacturerName ASC, p.productName ASC";
            $result = $con->query($sql) or die($con->error);
