        // ) Update Specific Inventory Section Product Reserved Amount And Availability By warehouseId warehouseSectionId productId
        public function updateSpecificInventorySectionProductReservedAmountAndAvailabilityBywarehouseIdwarehouseSectionIdproductId(
            $inventorySectionsProductsReserved, 
            $inventorySectionsProductsAvailability,
            $warehouseId,
            $warehouseSectionId,
            $productId
        ){
            $con = $GLOBALS["con"];
            $sql = "UPDATE "
                . "inventory_sections_products isp, "
                . "products p, "
                . "warehouse w, "
                . "warehouse_sections ws, "
                . "product_category pc, "
                . "product_manufacturer pm, "
                . "product_unit_types put, "
                . "product_unit_measure pum, "
                . "product_sell_unit_price psup "
                . "SET "
                . "isp.inventorySectionsProductsReserved = '$inventorySectionsProductsReserved',"
                . "isp.inventorySectionsProductsAvailability = '$inventorySectionsProductsAvailability' "
                . "WHERE "
                . "isp.warehouseId = w.warehouseId AND "
                . "isp.warehouseSectionId = ws.warehouseSectionId AND "
                . "isp.productId = p.productId AND "
                . "p.productCategoryId = pc.productCategoryId AND "
                . "p.productManufacturerId = pm.productManufacturerId AND " 
                . "pc.productUnitTypeId = put.productUnitTypeId  AND " 
                . "pc.productUnitMeasureId  = pum.productUnitMeasureId AND " 
                . "w.warehouseId = ws.warehouseId AND "
                . "w.warehouseId = '$warehouseId' AND "
                . "ws.warehouseSectionId = '$warehouseSectionId' AND "
                . "p.productId = '$productId'";
            $result = $con->query($sql);    
            return $result;
        }

