                . "ps.processStatusId  = '$processStatusId' AND "
                . "cr.clientRequestCompleted  = '0' AND "
                . "cr.clientRequestCancelStatus  = '0' AND "
                . "hdvr.hireDriverRequestRequestedStatus = '1'";
