        // ) Update Fleet To Nav Link Active D Block
        public function updateFleetDisplayToNavLinkActiveDBlock ($updatefleetId) {
            $con = $GLOBALS["con"];
            $sql1 = "UPDATE fleet SET fleetNavLink = 'nav-link'";
            $result1 = $con->query($sql1) or die($con->error); 
            $sql2 = "UPDATE fleet SET fleetNavLink = 'nav-link active' WHERE fleetId = '$updatefleetId'";
            $result2 =  $con->query($sql2) or die($con->error); 
            $sql3 = "UPDATE fleet SET roleDisplay = 'd-none'";
            $result3 =  $con->query($sql3) or die($con->error); 
            $sql4 = "UPDATE fleet SET roleDisplay = 'd-block' WHERE fleetId = '$updatefleetId'";
            $result4 = $con->query($sql4) or die($con->error); 
            return $result1." ".$result2." ".$result3." ".$result4;           
        }
        // ) Get All Specific Vehicles By Fleet
        public function getAllSpecificVehicleByFleet ($fleetId) {
            $con = $GLOBALS["con"];
            $sql = "SELECT * FROM "
                . "vehicle_manufacturers vmf, "
                . "vehicle_model vm, "
                . "class_of_vehicles cov, "
                . "fleet f, "
                . "vehicle_registration_number vrn, "
                . "vehicle v "
                . "WHERE "
                . "v.vehicleModelId = vm.vehicleModelId AND "
                . "v.classOfVehicleId = cov.classOfVehicleId AND "
                . "v.vehicleManufacturerId = vmf.vehicleManufacturerId AND "
                . "v.vehicleRegistrationNumberId  = vrn.vehicleRegistrationNumberId AND "
                . "f.fleetId = '$fleetId' AND "
                . "f.fleetId = v.fleetId AND "
                . "vm.vehicleManufacturerId = vmf.vehicleManufacturerId " 
                . "ORDER BY vmf.vehicleManufacturerName ASC";
            $result = $con->query($sql) or die($con->error);  
            return $result;
        }  
