            $fleetName, 
            $cityId, 
            $fleetLocation, 
            $fleetImageEdit
        ){
            $con = $GLOBALS["con"];
            if ($fleetImageEdit != "") {
                $sql = "INSERT INTO fleet("
                    . "fleetName,"
                    . "cityId,"
                    // . "fleetLocation,"
                    . "fleetImage_"
                    . ")VALUES("
                    . "'$fleetName',"
                    . "'$cityId',"
