                $sql = "INSERT INTO fleet("
                    . "fleetName,"
                    . "cityId"
                    // . "fleetLocation"
                    . ")VALUES("
                    . "'$fleetName',"
                    . "'$cityId'"
                    // . "'$fleetLocation'"
                    . ")";
            }
            $result = $con->query($sql) or die($con->error);
            return $result;        
        }
