        // Update Specific Fleet Overview
        public function updateSpecificFleetOverview(
            $fleetName, 
            $cityId,
            $fleetImageEdit,
            $fleetLocation,
            $fleetAddress,

            $updateFleetId
        ){
            $con = $GLOBALS["con"];
            if ($fleetImageEdit == "") {
                $sql = "UPDATE fleet SET "
                    . "fleetName = '$fleetName',"
                    . "fleetAddress = '$fleetAddress',"
                    . "cityId = '$cityId'"
                    // . "fleetLocation = '$fleetLocation'"
                    . "WHERE "
                    . "fleetId = '$updateFleetId'";     
                $con->query($sql) or die($con->error);
            } else if ($fleetImageEdit != "") {
                $sql = "UPDATE fleet SET "
                    . "fleetName = '$fleetName',"
                    . "fleetAddress = '$fleetAddress',"
                    . "cityId = '$cityId',"
                    // . "fleetLocation = '$fleetLocation',"
                    . "fleetImage_ = '$fleetImageEdit'"
                    . "WHERE "
                    . "fleetId = '$updateFleetId'";     
                $con->query($sql) or die($con->error);
            }
            
        }

