        // ) Get Specific Navigation Tab Type Active Navigation Tabs By navigationTabTypeId userId roleId
        public function getSpecificNavigationTabTypeActiveNavigationTabsByNavigationTabTypeIdUserIdRoleId ($userId, $roleId, $navigationTabTypeId) {
            $con = $GLOBALS["con"];
            $sql = "SELECT * FROM "
                . "navigation_tab nt, "
                . "role_navigation_tabs rnt, "
                . "user_navigation_tabs unt, "
                . "navigation_tab_type_navigation_tab nttnt, "
                . "navigation_tab_type ntt, "
                . "user_navigation_tab_type untt, "
                . "role_navigation_tab_type rntt  "
                . "WHERE "
                . "nt.navigationTabId = rnt.navigationTabId AND "
                . "nt.navigationTabId = unt.navigationTabId AND "
                . "nt.navigationTabId = nttnt.navigationTabId AND "

                . "rnt.navigationTabId = unt.navigationTabId AND "
                . "rnt.navigationTabId = nttnt.navigationTabId AND "
                . "rnt.roleId = rntt.roleId AND "

                . "unt.navigationTabId = nttnt.navigationTabId AND "
                . "unt.userId = untt.userId AND "

                . "nttnt.navigationTabTypeId = ntt.navigationTabTypeId  AND "              
                . "nttnt.navigationTabTypeId = untt.navigationTabTypeId  AND "              
                . "nttnt.navigationTabTypeId = rntt.navigationTabTypeId  AND "  

                . "ntt.navigationTabTypeId = untt.navigationTabTypeId  AND "              
                . "ntt.navigationTabTypeId = rntt.navigationTabTypeId  AND " 

                . "untt.navigationTabTypeId = rntt.navigationTabTypeId  AND "              
                                
                . "rnt.roleId = '$roleId' AND "
                . "unt.userId = '$userId' AND "

                . "nttnt.navigationTabTypeId = '$navigationTabTypeId' AND "
                . "nt.navigationTabStatus = '1'"
                . "ORDER BY nt.navigationTabName ASC";    
            $result = $con->query($sql);
            return $result;
        }
