    /* (109) Vehicle Dashboard Details */
        // ) Add New Vehicle Book
        public function addVehicleDashboardDetails(
            $vehicleOdometerDashboardValue,
            $vehicleDashboardFuelTankCapacity,
            $vehicleDashboardFuelAvailability,
            $fuelTypeId,
            $updateVehicleId
        ) {
            $con = $GLOBALS["con"];
            $sqlVehicleDashboardDetails= "INSERT INTO vehicle_dashboard("
                . "vehicleOdometerDashboardValue,"
                . "vehicleDashboardFuelTankCapacity,"

                . "vehicleDashboardFuelAvailability,"
                . "bowserTankFuelTypeId,"

                . "vehicleId"
                . ")VALUES("
                . "'$vehicleOdometerDashboardValue',"
                . "'$vehicleDashboardFuelTankCapacity',"

                . "'$vehicleDashboardFuelAvailability',"
                . "'$fuelTypeId',"

                . "'$updateVehicleId'"
                .")";   
            $con->query($sqlVehicleDashboardDetails) or die($con->error);
            $vehicleDashboardId  = $con->insert_id; 

            $sqlVehicle = "UPDATE vehicle v SET "
                . "v.vehicleDashboardId = '$vehicleDashboardId',"
                . "v.vehicleDashboardStatus = '1' WHERE "
                . "v.vehicleId = '$updateVehicleId'";
            $con->query($sqlVehicle) or die($con->error);
        } 
        // ) Get Specific Vehicle Dashboard Details
        public function getSpecificVehicleDashboardDetails ($vehicleId) {
            $con = $GLOBALS["con"];
            $sql = "SELECT * FROM "
                . "vehicle v, "
                . "vehicle_dashboard vd "
                . "WHERE "
                . "v.vehicleId = vd.vehicleId AND "
                . "v.vehicleId = '$vehicleId'";
            $result = $con->query($sql);
            return $result;       
        }
