        // ) Fleet Fuel Supply Request Assign Task For Vehicle   
        public function fleetFuelSupplyRequestAssignTaskForVehicle (
            $updateFleetFuelSupplyRequestId, 
            $vehicleId,
            $currentDate,
            $currentTime
        ){
            $con = $GLOBALS["con"];

            $sqlAddVehicleFuelSupplyTask = "INSERT INTO vehicle_fuel_supply_task("
                . "vehicleId,"
                . "fleetFuelSupplyRequestId,"
                . "vehicleFuelSupplyTaskDate,"
                . "vehicleFuelSupplyTaskTime"
                . ")VALUES("
                . "'$vehicleId',"
                . "'$updateFleetFuelSupplyRequestId',"
                . "'$currentDate',"
                . "'$currentTime'"
                . ")";
            $con->query($sqlAddVehicleFuelSupplyTask) or die($con->error);

            $sqlFleetFuelSupplyRequestAssignTaskForVehicle = "UPDATE fleet_fuel_supply_request ffsr SET "
            . "ffsr.vehicleTaskStatus = '1' WHERE "
            . "ffsr.fleetFuelSupplyRequestId = '$updateFleetFuelSupplyRequestId'";
            $con->query($sqlFleetFuelSupplyRequestAssignTaskForVehicle) or die($con->error);
            return $insert_id = $con->insert_id;  
        }
