    /* (123) Product Purchasing Request */
        /////////////////////////////////////////////////////////////////////////////////////////////////////
        // ) Add Product Purchasing Request 
        public function addProductPurchasingRequest(
            $clientRequestId, 
            $updateWarehouseId, 
            $updateWarehouseSectionId, 
            $updateProductId, 
            $requestProductAmount, 
            $productSellingPrice, 
            $currentDate, 
            $currentTime
        ) {
            $con = $GLOBALS["con"];
            $sql1 = "INSERT INTO product_purchasing_request("
                . "clientRequestId,"
                . "warehouseId,"
                . "warehouseSectionId,"
                . "productId,"
                . "requestProductAmount,"
                . "productSellingPrice,"
                . "productPurchasingRequestDate,"
                . "productPurchasingRequestTime"
                . ")VALUES("
                . "'$clientRequestId',"
                . "'$updateWarehouseId',"
                . "'$updateWarehouseSectionId',"
                . "'$updateProductId',"
                . "'$requestProductAmount',"
                . "'$productSellingPrice',"
                . "'$currentDate',"
                . "'$currentTime'"
                . ")";
            $con->query($sql1) or die($con->error);
            return $insert_id = $con->insert_id;  
        }
        // ) Get Specific Product Purchasing Request By clientRequestId clientServiceId clientUserId
        public function getSpecificProductPurchasingRequestByClientRequestIdClientServiceIdClientUserId($clientRequestId, $clientServiceId, $clientUserId){
            $con = $GLOBALS["con"];
            $sql = "SELECT * FROM "
                . "client_requests cr, "
                . "product_purchasing_request ppr, "
                . "client_services cs, "
                . "user u, "
                . "products p,"
                . "product_category pc, "
                . "product_manufacturer pm, "
                . "product_unit_types put, "
                . "product_unit_measure pum, "
                . "profile_image pi,"
                . "process_status ps, "
                . "Colors cssc, "
                . "warehouse w, "
                . "warehouse_sections ws "
                . "WHERE "
                . "cr.clientServiceId = cs.clientServiceId  AND "
                . "ppr.warehouseId = w.warehouseId  AND "
                . "ws.warehouseId = w.warehouseId  AND "
                . "ppr.warehouseSectionId = ws.warehouseSectionId  AND "
                . "cr.clientRequestId = ppr.clientRequestId  AND "
                . "cr.processStatusId  = ps.processStatusId   AND "
                . "cssc.ColorId   = ps.cssColorId   AND "
                . "u.profileImageId = pi.profileImageId AND "
                . "p.productId  = ppr.productId AND "
                . "p.productCategoryId = pc.productCategoryId AND "
                . "p.productManufacturerId = pm.productManufacturerId AND "
                . "pc.productUnitTypeId = put.productUnitTypeId  AND " 
                . "pc.productUnitMeasureId  = pum.productUnitMeasureId AND "
                . "cr.clientRequestId = '$clientRequestId' AND "
                . "cs.clientServiceId = '$clientServiceId' AND "
                . "u.userId = '$clientUserId'";
            $result = $con->query($sql) or die($con->error);
            return $result;
        }        
        // ) Inform Warehouse Inventory Section    
        public function informWarehouseInventorySection($productPurchasingRequestId){
            $con = $GLOBALS["con"];
            $sql = "UPDATE product_purchasing_request ppr SET "
                . "ppr.inventorSectionInformStatus = '1' WHERE "
                . "ppr.productPurchasingRequestId = '$productPurchasingRequestId'";
            $result = $con->query($sql);    
            return $result;
        }
