        // ) Get All Not Completed Not Cancelled Client Product Purchasing Requests     
        public function getAllSpecificWarehouseSectionNotCompletedNotCancelledClientProductPurchasingRequests($warehouseSectionId){
            $con = $GLOBALS["con"];
            $sql = "SELECT * FROM "
                . "product_purchasing_request ppr, "
                . "client_requests cr, "
                . "client_services cs, "
                . "colors cssc, "
                . "process_status ps, "
                . "warehouse w ,"
                . "warehouse_sections ws, "
                . "products p, "
                . "user u, "
                . "profile_image pi "
                . "WHERE "
                . "cr.clientRequestId = ppr.clientRequestId AND "
                . "cr.clientServiceId = cs.clientServiceId AND "
                . "ppr.warehouseId = w.warehouseId AND "
                . "w.warehouseId = ws.warehouseId AND "
                . "ppr.warehouseSectionId = ws.warehouseSectionId AND "
                . "ppr.productId = p.productId AND "
