        // ) Add Client Request for Hire ADR Certificate Driver and Vehicle Requests By clientRequestId, classOfVehicleId, fleetId
        public function addHireADRCertificateDriverAndVehicleClient (
            $clientRequestId, 
            $driverVehicleClassOfVehicleId, 
            $ADRCertificateId, 
            $fleetId,
            $currentDate, 
            $currentTime
        ){
            $con = $GLOBALS["con"];
            $sql1 = "INSERT INTO hire_adr_certificate_driver_and_vehicle_request("
                . "clientRequestId,"
                . "driverVehicleClassOfVehicleId,"
                . "fleetId,"
                . "ADRCertificateId,"
                . "hireADRCertificateDriverAndVehicleRequestDate,"
                . "hireADRCertificateDriverAndVehicleRequestTime"
                . ")VALUES("
                . "'$clientRequestId',"
                . "'$driverVehicleClassOfVehicleId',"
                . "'$fleetId',"
                . "'$ADRCertificateId',"
                . "'$currentDate',"
                . "'$currentTime'"
                . ")";
            $con->query($sql1) or die($con->error);
            return $insert_id = $con->insert_id;  
        }
        // ) Hire ADR Certificate Driver and Vehicle Request Driver Requesting
        public function hireADRCertificateDriverAndVehicleRequestDriverRequesting ($hireADRCertificateDriverAndVehicleRequestId) {
            $con = $GLOBALS["con"];
            $sql = "UPDATE hire_adr_certificate_driver_and_vehicle_request hadrcdvr SET "
                . "hadrcdvr.hireADRCertificateDriverRequestRequestedStatus = '1' WHERE "
                . "hadrcdvr.hireADRCertificateDriverAndVehicleRequestId = '$hireADRCertificateDriverAndVehicleRequestId'";
            $result = $con->query($sql);    
            return $result;
        } 
