        // ) Get Specific Hire ADR Certificate Driver And Vehicle Request
        public function getSpecificHireADRCertificateDriverAndVehicleRequest ($hireADRCertificateDriverAndVehicleRequestId) {
            $con = $GLOBALS["con"];
            $sql = "SELECT * FROM "
                . "hire_adr_certificate_driver_and_vehicle_request hadrcdvr, "
                . "client_requests cr, "
                . "class_of_vehicles cov, "
                . "adr_certificates adrc, "
                . "process_status ps, "
                . "fleet f, "
                . "colors cssc "
                . "WHERE "
                . "hadrcdvr.driverVehicleClassOfVehicleId = cov.classOfVehicleId AND "
                . "hadrcdvr.ADRCertificateId = adrc.ADRCertificateId AND "
                . "hadrcdvr.clientRequestId  = cr.clientRequestId AND "
                . "cr.processStatusId  = ps.processStatusId AND "
                . "ps.cssColorId  = cssc.ColorId AND "
                . "f.fleetId = hadrcdvr.fleetId AND "
                . "hadrcdvr.hireADRCertificateDriverAndVehicleRequestId = '$hireADRCertificateDriverAndVehicleRequestId'";
            $result = $con->query($sql) or die($con->error);
            return $result;
        }
