        // ) Get All Available Hire ADR Certificate Driver and Vehicle Request By Requested Status     
        public function getAllAvailableHireADRCertificateDriverandVehicleRequestByDriverRequestedStatus () {
            $con = $GLOBALS["con"];
            $sql = "SELECT * FROM "
                . "hire_adr_certificate_driver_and_vehicle_request hadrcdvr, "
                . "client_requests cr, "
                . "client_services cs, "
                . "class_of_vehicles cov, "
                . "adr_certificates adrc, "
                . "process_status ps, "
                . "colors cssc, "
                . "user u, "
                . "profile_image pi "
                . "WHERE "
                . "cr.clientRequestId = hadrcdvr.clientRequestId AND "
                . "cr.clientServiceId = cs.clientServiceId AND "
                . "cov.classOfVehicleId  = hadrcdvr.driverVehicleClassOfVehicleId AND "
                . "hadrcdvr.ADRCertificateId = adrc.ADRCertificateId AND "
                . "u.userId  = cr.clientUserId AND "
                . "u.profileImageId  = pi.profileImageId AND "
                . "cr.processStatusId  = ps.processStatusId AND "
                . "ps.cssColorId  = cssc.ColorId AND "
                . "cr.clientRequestCompleted  = '0' AND "
                . "cr.clientRequestCancelStatus  = '0' AND "
                . "hadrcdvr.hireADRCertificateDriverRequestRequestedStatus = '1'";
            $result= $con->query($sql);
            return $result;
        }
