        // ) Get Hire ADR Certificate Driver and Vehicle Request By Vehicle Requested Status processStatusId fleetId     
        public function getAllAvailableClientHireADRCertificateDriverAndVehicleRequestsByVehicleRequestedprocessStatusIdfleetId ($processStatusId, $fleetId) {
            $con = $GLOBALS["con"];
            $sql = "SELECT COUNT(*) as allCount FROM "
                . "hire_adr_certificate_driver_and_vehicle_request hadrcdvr, "
                . "client_requests cr, "
                . "client_services cs, "
                . "class_of_vehicles cov, "
                . "adr_certificates adrc, "
                . "process_status ps, "
                . "colors cssc, "
                . "fleet f, "
                . "user u, "
                . "profile_image pi "
                . "WHERE "
                . "cr.clientRequestId = hadrcdvr.clientRequestId AND "
                . "f.fleetId = hadrcdvr.fleetId AND "
                . "cr.clientServiceId = cs.clientServiceId AND "
                . "cov.classOfVehicleId  = hadrcdvr.driverVehicleClassOfVehicleId AND "
                . "hadrcdvr.ADRCertificateId = adrc.ADRCertificateId AND "
                . "u.userId  = cr.clientUserId AND "
                . "u.profileImageId  = pi.profileImageId AND "
                . "cr.processStatusId  = ps.processStatusId AND "
                . "ps.cssColorId  = cssc.ColorId AND "
                . "ps.processStatusId  = '$processStatusId' AND "
                . "f.fleetId  = '$fleetId' AND "
                . "hadrcdvr.hireVehicleRequestRequestedStatus = '1'";
            $result = $con->query($sql) or die($con->error);
            $countRow = $result->fetch_assoc();
            $allCount = $countRow["allCount"];
            return $allCount;
        }
