        // ) Get Available Specific Supplier Requests By supplierServiceId Count
        public function getAvailableSpecificSupplierRequestsBysupplierServiceIdCount ($supplierServiceId) {
            $con = $GLOBALS["con"];
            $sql = "SELECT COUNT(*) as allCount FROM "
                . "supplier_requests sr, "
                . "supplier_request_transfer srt, "
                . "supplier_service ss, "
                . "supplier s, "
                . "user u, "
                . "profile_image pi, "
                . "process_status ps, "
                . "colors cssc "
                . "WHERE "
                . "sr.supplierUserId = u.userId AND "
                . "sr.supplierRequestId  = srt.supplierRequestId  AND "
                . "cssc.colorId = ps.cssColorId AND "
                . "s.userId = u.userId AND "
                . "u.profileImageId = pi.profileImageId AND "
                . "ps.processStatusId = sr.processStatusId AND "
                . "ss.supplierServiceId = sr.supplierServiceId AND "
                . "ss.supplierServiceId = '$supplierServiceId' AND "
                . "sr.supplierRequestCompleted = '0' AND "
                . "sr.supplierRequestCancelStatus = '0'";
            $result = $con->query($sql) or die($con->error);
            $countRow = $result->fetch_assoc();
            $allCount = $countRow["allCount"];
            return $allCount;
        }
