        public function addPaymentInvoiceToSupplierRequest($filename, $supplierRequestId, $payment){
            $con = $GLOBALS["con"];
            $sql = "UPDATE supplier_requests sr SET "
                . "sr.supplierRequestPaymentInvoice = '$filename',"
                . "sr.supplierRequestPaymentInvoiceStatus = '1',"
                . "sr.payment = '$payment'"
                . "WHERE "
                . "sr.supplierRequestId   = '$supplierRequestId'";
            $result = $con->query($sql);    
            return $result;
        } 
        // ) Add Supplier Request     
        public function addSupplierRequest(
            $processStatusId,
