                . "financeId,"
                . "financeTypeId,"
                . "supplierRequestDate,"
                . "supplierRequestTime"
                . ")VALUES("
                . "'$processStatusId',"
                . "'$financeId',"
                . "'$financeTypeId',"
                . "'$currentDate',"
                . "'$currentTime'"
                . ")";
            $con->query($sql1) or die($con->error);
            return $insert_id = $con->insert_id;  
        }
