            $sql = "UPDATE supplier_loyalty_membership slm SET "
                . "slm.supplierLoyaltyMembershipName = '$supplierLoyaltyMembershipName',"
                . "slm.supplierLoyaltyMembershipStartPointValue = '$supplierLoyaltyMembershipStartPointValue',"
                . "slm.bootstrapCSSColorId = '$bootstrapCSSColorId',"
                . "slm.supplierLoyaltyMembershipStatus = '$supplierLoyaltyMembershipStatus'"
                . "WHERE "
                . "slm.supplierLoyaltyMembershipId = '$updateSupplierLoyaltyMembershipId'";
