        // Get Specific Finance By financeTypeId
        public function getSpecificFinanceByfinanceTypeId($financeTypeId){
            $conn = $GLOBALS["con"];
            $sql = "SELECT * FROM "
                . "finance_type ft, "
                . "finance f "
                . "WHERE "
                . "f.financeTypeId = ft.financeTypeId AND "
                . "ft.financeTypeId = '$financeTypeId'";
            $result = $conn->query($sql) or die($conn->error);
            return $result;
        }
        // Get Specific Finance By financeTypeId
        public function getSpecificFinanceByfinanceTypeId1($financeTypeId){
            $conn = $GLOBALS["con"];
            $sql = "SELECT * FROM "
                . "finance_type ft, "
                . "client_requests cr, "
                . "client_services cs, "
                . "finance f "
                . "WHERE "
                . "f.financeTypeId = ft.financeTypeId AND "
                . "cr.financeId = f.financeId AND "
                . "cs.clientServiceId = cr.clientServiceId AND "
                . "cr.clientRequestCompleted = '1' AND "
                . "ft.financeTypeId = '$financeTypeId'";
            $result = $conn->query($sql) or die($conn->error);
            return $result;
        }
